css:
body :where([data-bz-node="pc"]) .bz-block{padding:0}
body :where([data-bz-node="pc"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="pc"]>.bz-container{padding-inline:0}

body [data-bz-node="pc"]{background:#fff;padding:30px 0 90px}
body [data-bz-node="pc"]>.bz-container{max-width:var(--container)}
body [data-bz-node="pc-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="pc-intro"] .bz-text{max-width:none;margin-top:22px}
body [data-bz-node="pc-intro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node="pc-grid"]{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr));gap:24px;margin-top:36px;align-items:stretch}
body [data-bz-node="pc-grid"]>.bz-col{grid-column:auto}
body [data-bz-node^="pc-card-"]{display:flex;flex-direction:column;background:#fff;border:1px solid #d4d4d2}
body [data-bz-node^="pc-img-"] figure{margin:0}
body [data-bz-node^="pc-img-"] img{width:100%;height:auto;border-radius:0}
body [data-bz-node^="pc-title-"]{padding:0 28px;margin-top:26px}
body [data-bz-node^="pc-title-"] h3{font:700 20px/1.2 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--accent);margin:0}
body [data-bz-node^="pc-text-"]{padding:0 28px;margin-top:14px}
body [data-bz-node^="pc-text-"] p{font:400 12.5px/1.6 var(--font-body);color:#555;margin:0}
body [data-bz-node^="pc-cta-"]{padding:0 28px 28px;margin-top:20px}
body [data-bz-node^="pc-cta-"] .bz-btns{margin:0}
body [data-bz-node^="pc-cta-"] .bz-btn{padding:0;border:0;background:none;color:var(--accent);font:700 11px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;text-decoration:none}
body [data-bz-node^="pc-cta-"] .bz-btn:hover{color:var(--accent-dark);text-decoration:underline}
@media (max-width:1100px){body [data-bz-node="pc"]{padding:20px 24px 64px}body [data-bz-node="pc-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="pc"]{padding:16px 20px 48px}body [data-bz-node="pc-h"] h2{font-size:26px}}
